// The native conversation's protocol, both ends generated by
// `tool/prepare.sh`: the app sends the conversation as the core lays it out
// (`lib/app/transcript/`), a row at a time and only the rows that changed;
// the client draws each by its kind and says back what the user did, by row
// key and node id. Every rule — what a row holds, when a spinner shows, what
// may be done to a message — is the app's. See "The conversation, natively"
// in lib/ui/chat/AGENTS.md.

// ignore_for_file: not_initialized_non_nullable_instance_field

import "package:pigeon/pigeon.dart";

@ConfigurePigeon(
  PigeonOptions(
    dartPackageName: "entoli_glass",
    dartOut: "packages/entoli_glass/lib/src/transcript_contract.g.dart",
    dartTestOut: "test/ui/shell/native_transcript.g.dart",
    swiftOut:
        "packages/entoli_glass/darwin/entoli_glass/Sources/entoli_glass/Contract/TranscriptContract.g.swift",
    swiftOptions: SwiftOptions(includeErrorClass: false),
  ),
)
/// The core's `TranscriptGlyph`, name for name.
enum TranscriptIcon {
  terminal,
  thinking,
  file,
  edit,
  search,
  web,
  subAgent,
  question,
  permissionGranted,
  permissionDenied,
  plan,
  artifact,
  skill,
  folderAdd,
  shield,
  error,
  goalActive,
  goalPaused,
  goalMet,
  goalBlocked,
  goalResumed,
  goalCleared,
  info,
}

/// The core's `BubbleTint`.
enum Tint { none, prompt, command, notice, tool, system }

enum RowKind { message, mode, compaction, compactionFailed, goal }

enum BlockKind { bubble, activity, activityRun, file, shellRun, steer }

enum SaidKind { prose, error, command }

enum TrailingKind { waiting, liveOutput, retry }

enum NodeKind { label, diff, plan, output }

enum OutputKind { artifact, skill }

enum TextKind { paragraph, heading, code, formula, rule, table }

enum InlineKind { text, formula, lineBreak, image }

enum CellAlign { start, center, end }

/// A run of words and how it is marked, a formula by its picture's id.
class InlineSnapshot {
  InlineSnapshot({
    this.kind = InlineKind.text,
    this.text = "",
    this.bold = false,
    this.italic = false,
    this.code = false,
    this.strike = false,
    this.link,
    this.formula,
  });

  InlineKind kind;
  String text;
  bool bold;
  bool italic;
  bool code;
  bool strike;
  String? link;
  int? formula;
}

/// The list item a block sits in, outermost first.
class MarkerSnapshot {
  MarkerSnapshot({
    this.ordered = false,
    this.number = 1,
    this.first = true,
    this.checked,
  });

  bool ordered;
  int number;

  /// The item's first block, which wears the marker.
  bool first;
  bool? checked;
}

class CodeTokenSnapshot {
  CodeTokenSnapshot({this.text = "", this.scope});

  String text;
  String? scope;
}

class CellSnapshot {
  CellSnapshot({
    this.row = 0,
    this.column = 0,
    this.header = false,
    this.inlines = const [],
  });

  int row;
  int column;
  bool header;
  List<InlineSnapshot> inlines;
}

/// One block of markdown: where it is nested, and what it is.
class TextBlockSnapshot {
  TextBlockSnapshot({
    this.kind = TextKind.paragraph,
    this.quotes = 0,
    this.items = const [],
    this.level = 0,
    this.inlines = const [],
    this.language,
    this.code = "",
    this.tokens = const [],
    this.formula,
    this.written = "",
    this.columns = 0,
    this.align = const [],
    this.cells = const [],
  });

  TextKind kind;
  int quotes;
  List<MarkerSnapshot> items;
  int level;
  List<InlineSnapshot> inlines;
  String? language;
  String code;
  List<CodeTokenSnapshot> tokens;
  int? formula;

  /// The TeX as written, a formula's copy and its alt text.
  String written;
  int columns;
  List<CellAlign> align;
  List<CellSnapshot> cells;
}

/// A typeset formula: PNG at [scale] pixels a point, sent once per id.
class FormulaPicture {
  FormulaPicture({
    this.id = 0,
    required this.png,
    this.scale = 2,
    this.width = 0,
    this.height = 0,
    this.baseline = 0,
  });

  int id;
  Uint8List png;
  double scale;
  double width;
  double height;
  double baseline;
}

class SaidSnapshot {
  SaidSnapshot({
    this.kind = SaidKind.prose,
    this.blocks = const [],
    this.text = "",
    this.caret = false,
  });

  SaidKind kind;
  List<TextBlockSnapshot> blocks;
  String text;
  bool caret;
}

class TrailingSnapshot {
  TrailingSnapshot({
    this.kind = TrailingKind.waiting,
    this.line,
    this.isError = false,
  });

  TrailingKind kind;
  String? line;
  bool isError;
}

/// An attached file: its name and, where this device has it, where.
class FileSnapshot {
  FileSnapshot({this.name = "", this.mime, this.path});

  String name;
  String? mime;
  String? path;
}

class PlanTaskSnapshot {
  PlanTaskSnapshot({this.title = "", this.done = false});

  String title;
  bool done;
}

/// An activity as the core's node says it is drawn. [id] is what an intent
/// names it by.
class NodeSnapshot {
  NodeSnapshot({
    this.id = "",
    this.kind = NodeKind.label,
    this.icon = TranscriptIcon.terminal,
    this.text = "",
    this.isError = false,
    this.busy = false,
    this.tail,
    this.removed = const [],
    this.added = const [],
    this.output = OutputKind.artifact,
    this.progress,
    this.tasks = const [],
  });

  String id;
  NodeKind kind;
  TranscriptIcon icon;
  String text;
  bool isError;
  bool busy;
  String? tail;
  List<String> removed;
  List<String> added;
  OutputKind output;
  String? progress;
  List<PlanTaskSnapshot> tasks;
}

class ShellRunSnapshot {
  ShellRunSnapshot({this.command = "", this.output = "", this.exitCode});

  String command;
  String output;
  int? exitCode;
}

class BlockSnapshot {
  BlockSnapshot({
    this.kind = BlockKind.bubble,
    this.tint = Tint.none,
    this.heading,
    this.files = const [],
    this.said = const [],
    this.trailing = const [],
    this.nodes = const [],
    this.runStart = 0,
    this.shell,
  });

  BlockKind kind;
  Tint tint;
  String? heading;
  List<FileSnapshot> files;
  List<SaidSnapshot> said;
  List<TrailingSnapshot> trailing;
  List<NodeSnapshot> nodes;
  int runStart;
  ShellRunSnapshot? shell;
}

/// What can be done to a message, as the core's `MessageActions` says.
class ActionsSnapshot {
  ActionsSnapshot({
    this.copy = false,
    this.threads,
    this.previous = false,
    this.next = false,
    this.delete = false,
    this.deleteQuestion = "",
    this.edit = false,
    this.editText = "",
    this.regenerate = false,
    this.react = false,
    this.speak = false,
    this.speaking = false,
  });

  bool copy;
  String? threads;
  bool previous;
  bool next;
  bool delete;
  String deleteQuestion;
  bool edit;
  String editText;
  bool regenerate;
  bool react;
  bool speak;
  bool speaking;
}

class MessageSnapshot {
  MessageSnapshot({
    this.user = false,
    this.speaker,
    this.tint = Tint.none,
    this.face,
    this.blocks = const [],
    required this.actions,
    this.reactions = const [],
  });

  bool user;
  String? speaker;
  Tint tint;
  Uint8List? face;
  List<BlockSnapshot> blocks;
  ActionsSnapshot actions;
  List<String> reactions;
}

/// One row, under [key], which is stable across a streamed delta.
class RowSnapshot {
  RowSnapshot({
    this.key = "",
    this.kind = RowKind.message,
    this.text = "",
    this.body = const [],
    this.icon = TranscriptIcon.info,
    this.isError = false,
    this.message,
  });

  String key;
  RowKind kind;
  String text;
  List<TextBlockSnapshot> body;
  TranscriptIcon icon;
  bool isError;
  MessageSnapshot? message;
}

/// The conversation: every row's key in order, and the rows that changed
/// since the last snapshot of the same chat — a client keeps the rest.
/// [flutterBottom] is how much of the foot Flutter still draws above the
/// composer — the browser's prompts, a setup bar — which the conversation
/// leaves clear.
class ConversationSnapshot {
  ConversationSnapshot({
    this.chatId,
    this.order = const [],
    this.changed = const [],
    this.running = false,
    this.flutterBottom = 0,
    this.reactions = const [],
  });

  String? chatId;
  List<String> order;
  List<RowSnapshot> changed;
  bool running;
  double flutterBottom;

  /// The reactions a message can be given, in the order offered.
  List<String> reactions;
}

class SectionSnapshot {
  SectionSnapshot({this.label, this.body = "", this.isError = false});

  String? label;
  String body;
  bool isError;
}

class DetailActionSnapshot {
  DetailActionSnapshot({this.label = "", this.enabled = true, this.why});

  String label;
  bool enabled;
  String? why;
}

/// The detail page open over the conversation, or nothing where [present]
/// is false.
class DetailSnapshot {
  DetailSnapshot({
    this.present = false,
    this.title = "",
    this.icon,
    this.command,
    this.status,
    this.statusError = false,
    this.sections = const [],
    this.actions = const [],
    this.mono = false,
    this.live = false,
    this.transcript,
  });

  bool present;
  String title;
  TranscriptIcon? icon;
  String? command;
  String? status;
  bool statusError;
  List<SectionSnapshot> sections;
  List<DetailActionSnapshot> actions;
  bool mono;
  bool live;

  /// A sub-agent's reply, its nodes' ids opening details of their own.
  MessageSnapshot? transcript;
}

@HostApi(dartHostTestHandler: "TestNativeTranscript")
abstract class NativeTranscript {
  void conversation(ConversationSnapshot snapshot);
  void formulas(List<FormulaPicture> pictures);
  void detail(DetailSnapshot snapshot);
}

enum MessageAction { copy, copyRaw, previous, next, delete, regenerate, speak }

@FlutterApi()
abstract class TranscriptIntents {
  /// A node tapped: its detail, or for a card, what it opens.
  void open(String node);

  void closeDetail();
  void detailAction(int index);
  void link(String href);
  void act(String row, MessageAction action);
  void edit(String row, String text);
  void react(String row, String emoji);
  void retry(String row);
  void openPlan();
  void openFile(String row, int block, int file);
}
